class Account {
    private int balance;
    private int fee;
    public Account(int b) {
        balance = b;
        fee = 2;
    }
    public boolean withdraw(int amt) {
        if (amt + fee <= balance) {
            balance -= amt + fee;
            return true;
        }
        return false;
    }
    public int getBalance() {
        return balance;
    }
}
```

